(function() {
  var htmlContent = "\n<div id=\"cs-october-promos-root\" class=\"cs-oct-scope\">\n  <style>\n\n  .cs-oct-scope {\n    --cs-bg-light: #ffffff;\n    --cs-bg-card: #fcfcfc;\n    --cs-bg-dark: #171717;\n    --cs-text-primary: #171717;\n    --cs-text-muted: #555555;\n    --cs-text-light: #f7f7f7;\n    --cs-accent-gold: #c5a265;\n    --cs-accent-gold-hover: #b08d51;\n    --cs-border-color: #e5e5e5;\n    --cs-border-dark: #2a2a2a;\n    --cs-font-title: \"Forum\", Georgia, \"Times New Roman\", serif;\n    --cs-font-body: \"Montserrat\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n    --cs-radius: 0px; /* Строгая премиальная геометрия клиники */\n    \n    font-family: var(--cs-font-body);\n    color: var(--cs-text-primary);\n    box-sizing: border-box;\n    line-height: 1.5;\n    -webkit-font-smoothing: antialiased;\n  }\n\n  .cs-oct-scope *,\n  .cs-oct-scope *::before,\n  .cs-oct-scope *::after {\n    box-sizing: border-box;\n  }\n\n  #cs-october-promos-root {\n    max-width: 1200px;\n    margin: 40px auto 60px;\n    padding: 0 20px;\n  }\n\n  /* Шапка секции */\n  .cs-oct-header {\n    text-align: center;\n    margin-bottom: 36px;\n  }\n  .cs-oct-subtitle {\n    font-size: 13px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.16em;\n    color: var(--cs-accent-gold);\n    margin-bottom: 12px;\n  }\n  .cs-oct-title {\n    font-family: var(--cs-font-title);\n    font-size: 38px;\n    font-weight: 400;\n    line-height: 1.2;\n    color: var(--cs-text-primary);\n    margin: 0 0 16px;\n    letter-spacing: 0.02em;\n  }\n  .cs-oct-intro {\n    font-size: 15px;\n    color: var(--cs-text-muted);\n    max-width: 680px;\n    margin: 0 auto;\n    line-height: 1.6;\n  }\n\n  /* Главный Hero-баннер (во всю ширину) */\n  .cs-oct-flash-banner {\n    background: var(--cs-bg-dark);\n    color: var(--cs-text-light);\n    border: 1px solid var(--cs-border-dark);\n    display: grid;\n    grid-template-columns: 1.15fr 0.85fr;\n    gap: 36px;\n    margin-bottom: 32px;\n    align-items: stretch;\n    box-shadow: 0 12px 36px rgba(0, 0, 0, 0.08);\n  }\n  .cs-oct-flash-content {\n    padding: 44px 40px;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n  }\n  .cs-oct-flash-tagline {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    margin-bottom: 16px;\n  }\n  .cs-oct-badge-flash {\n    background: var(--cs-accent-gold);\n    color: #ffffff;\n    font-size: 11px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.12em;\n    padding: 5px 12px;\n    display: inline-block;\n  }\n  .cs-oct-flash-date {\n    font-size: 13px;\n    color: #a0a0a0;\n    letter-spacing: 0.04em;\n  }\n  .cs-oct-flash-title {\n    font-family: var(--cs-font-title);\n    font-size: 32px;\n    font-weight: 400;\n    color: #ffffff;\n    margin: 0 0 14px;\n    line-height: 1.25;\n  }\n  .cs-oct-flash-offer {\n    font-size: 18px;\n    font-weight: 600;\n    color: var(--cs-accent-gold);\n    margin-bottom: 16px;\n  }\n  .cs-oct-flash-offer mark {\n    background: transparent;\n    color: #ffffff;\n    font-weight: 700;\n  }\n  .cs-oct-flash-text {\n    font-size: 14px;\n    color: #cccccc;\n    line-height: 1.6;\n    margin: 0 0 24px;\n  }\n  .cs-oct-flash-features {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 10px 18px;\n    margin-bottom: 30px;\n    font-size: 13px;\n    color: #e0e0e0;\n  }\n  .cs-oct-feature-item {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .cs-oct-feature-bullet {\n    width: 6px;\n    height: 6px;\n    background: var(--cs-accent-gold);\n    flex-shrink: 0;\n  }\n  .cs-oct-flash-actions-inline {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    flex-wrap: wrap;\n  }\n  .cs-oct-flash-media {\n    position: relative;\n    overflow: hidden;\n    min-height: 320px;\n    background: #000;\n    border-left: 1px solid rgba(255, 255, 255, 0.08);\n  }\n  .cs-oct-flash-img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n    display: block;\n    transition: transform 0.6s cubic-bezier(0.2, 0, 0.2, 1);\n  }\n  .cs-oct-flash-banner:hover .cs-oct-flash-img {\n    transform: scale(1.03);\n  }\n\n  /* Сетка из 3 программ месяца */\n  .cs-oct-cards-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 24px;\n    margin-bottom: 32px;\n  }\n  .cs-oct-card {\n    background: var(--cs-bg-card);\n    border: 1px solid var(--cs-border-color);\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n    transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;\n    position: relative;\n  }\n  .cs-oct-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.06);\n    border-color: #d0d0d0;\n  }\n  .cs-card-media {\n    position: relative;\n    width: 100%;\n    height: 220px;\n    overflow: hidden;\n    background: #171717;\n  }\n  .cs-card-img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n    display: block;\n    transition: transform 0.5s ease;\n  }\n  .cs-oct-card:hover .cs-card-img {\n    transform: scale(1.04);\n  }\n  .cs-card-badge {\n    position: absolute;\n    top: 14px;\n    left: 14px;\n    background: rgba(23, 23, 23, 0.88);\n    backdrop-filter: blur(4px);\n    color: var(--cs-accent-gold);\n    font-size: 10px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.12em;\n    padding: 5px 10px;\n    border: 1px solid rgba(197, 162, 101, 0.35);\n  }\n  .cs-card-body {\n    padding: 26px 24px 26px;\n    display: flex;\n    flex-direction: column;\n    flex-grow: 1;\n    justify-content: space-between;\n  }\n  .cs-card-title {\n    font-family: var(--cs-font-title);\n    font-size: 23px;\n    font-weight: 400;\n    color: var(--cs-text-primary);\n    margin: 0 0 10px;\n    line-height: 1.28;\n  }\n  .cs-card-aim {\n    font-size: 13px;\n    color: var(--cs-text-muted);\n    margin-bottom: 16px;\n    line-height: 1.5;\n    font-style: italic;\n  }\n  .cs-card-list {\n    list-style: none;\n    padding: 0;\n    margin: 0 0 22px;\n    font-size: 13px;\n    color: #444444;\n  }\n  .cs-card-list li {\n    position: relative;\n    padding-left: 16px;\n    margin-bottom: 8px;\n    line-height: 1.45;\n  }\n  .cs-card-list li::before {\n    content: \"—\";\n    position: absolute;\n    left: 0;\n    color: var(--cs-accent-gold);\n  }\n  .cs-card-value-box {\n    border-top: 1px solid var(--cs-border-color);\n    padding-top: 18px;\n    margin-bottom: 22px;\n  }\n  .cs-card-value-main {\n    font-size: 17px;\n    font-weight: 700;\n    color: var(--cs-text-primary);\n    margin-bottom: 6px;\n  }\n  .cs-card-value-sub {\n    font-size: 12px;\n    color: var(--cs-text-muted);\n    line-height: 1.45;\n  }\n  .cs-card-limit-note {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    font-size: 11px;\n    font-weight: 600;\n    color: var(--cs-accent-gold-hover);\n    margin-top: 8px;\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n  }\n  .cs-card-limit-dot {\n    width: 6px;\n    height: 6px;\n    background: var(--cs-accent-gold);\n    border-radius: 50%;\n  }\n  .cs-card-actions {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    margin-top: auto;\n  }\n\n  /* Кнопки */\n  .cs-btn-primary-gold {\n    display: inline-block;\n    background: var(--cs-accent-gold);\n    color: #ffffff !important;\n    text-decoration: none;\n    font-size: 12px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.12em;\n    padding: 14px 26px;\n    border: none;\n    cursor: pointer;\n    transition: background 0.25s ease, transform 0.2s ease;\n    text-align: center;\n  }\n  .cs-btn-primary-gold:hover {\n    background: var(--cs-accent-gold-hover);\n  }\n  .cs-btn-primary-black {\n    flex-grow: 1;\n    display: inline-block;\n    background: var(--cs-bg-dark);\n    color: #ffffff !important;\n    text-decoration: none;\n    font-size: 12px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.1em;\n    padding: 13px 18px;\n    border: 1px solid var(--cs-bg-dark);\n    cursor: pointer;\n    transition: background 0.25s ease, border-color 0.25s ease;\n    text-align: center;\n  }\n  .cs-btn-primary-black:hover {\n    background: #333333;\n    border-color: #333333;\n  }\n  .cs-btn-outline-details {\n    display: inline-block;\n    background: transparent;\n    color: var(--cs-text-primary);\n    text-decoration: none;\n    font-size: 12px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.08em;\n    padding: 12px 14px;\n    border: 1px solid var(--cs-border-color);\n    cursor: pointer;\n    transition: border-color 0.2s ease, background 0.2s ease;\n  }\n  .cs-btn-outline-details:hover {\n    border-color: var(--cs-text-primary);\n    background: #f5f5f5;\n  }\n  .cs-btn-link-white {\n    background: transparent;\n    border: none;\n    color: #cccccc;\n    font-size: 13px;\n    cursor: pointer;\n    padding: 8px 0;\n    text-decoration: underline;\n    text-underline-offset: 4px;\n    transition: color 0.2s ease;\n  }\n  .cs-btn-link-white:hover {\n    color: #ffffff;\n  }\n\n  /* Дисклеймер */\n  .cs-oct-disclaimer {\n    border-top: 1px solid var(--cs-border-color);\n    padding-top: 20px;\n    font-size: 12px;\n    color: #888888;\n    line-height: 1.6;\n    text-align: center;\n  }\n\n  /* Модальные окна */\n  .cs-modal-backdrop {\n    display: none;\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100vw;\n    height: 100vh;\n    background: rgba(0, 0, 0, 0.72);\n    backdrop-filter: blur(4px);\n    z-index: 999999;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n  }\n  .cs-modal-backdrop.is-active {\n    display: flex;\n  }\n  .cs-modal-dialog {\n    background: #ffffff;\n    max-width: 620px;\n    width: 100%;\n    max-height: 90vh;\n    overflow-y: auto;\n    position: relative;\n    padding: 38px 34px;\n    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);\n    border: 1px solid var(--cs-border-color);\n  }\n  .cs-modal-close {\n    position: absolute;\n    top: 18px;\n    right: 18px;\n    background: transparent;\n    border: none;\n    font-size: 26px;\n    line-height: 1;\n    cursor: pointer;\n    color: #888888;\n    transition: color 0.2s;\n  }\n  .cs-modal-close:hover {\n    color: #171717;\n  }\n  .cs-modal-badge {\n    font-size: 11px;\n    font-weight: 700;\n    color: var(--cs-accent-gold);\n    text-transform: uppercase;\n    letter-spacing: 0.12em;\n    margin-bottom: 8px;\n  }\n  .cs-modal-title {\n    font-family: var(--cs-font-title);\n    font-size: 26px;\n    font-weight: 400;\n    color: var(--cs-text-primary);\n    margin: 0 0 20px;\n    line-height: 1.25;\n  }\n  .cs-modal-body {\n    font-size: 14px;\n    color: #444444;\n    line-height: 1.65;\n  }\n  .cs-modal-body h4 {\n    font-size: 14px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.06em;\n    color: var(--cs-text-primary);\n    margin: 18px 0 8px;\n  }\n  .cs-modal-body ul {\n    margin: 8px 0 16px;\n    padding-left: 20px;\n  }\n  .cs-modal-body li {\n    margin-bottom: 6px;\n  }\n  .cs-modal-footer {\n    margin-top: 28px;\n    padding-top: 20px;\n    border-top: 1px solid var(--cs-border-color);\n    display: flex;\n    justify-content: flex-end;\n  }\n\n  /* Fallback popup */\n  .cs-fallback-form-group {\n    margin-bottom: 16px;\n  }\n  .cs-fallback-form-group label {\n    display: block;\n    font-size: 11px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.08em;\n    margin-bottom: 6px;\n    color: #555555;\n  }\n  .cs-fallback-form-group input {\n    width: 100%;\n    padding: 14px;\n    border: 1px solid #cccccc;\n    font-family: inherit;\n    font-size: 14px;\n    outline: none;\n    transition: border-color 0.2s;\n  }\n  .cs-fallback-form-group input:focus {\n    border-color: #171717;\n  }\n  .cs-fallback-form-group input[readonly] {\n    background: #f7f7f7;\n    border-color: #e5e5e5;\n    color: #171717;\n    font-weight: 600;\n  }\n\n  /* Адаптивность */\n  @media (max-width: 959px) {\n    .cs-oct-cards-grid {\n      grid-template-columns: 1fr;\n    }\n    .cs-oct-flash-banner {\n      grid-template-columns: 1fr;\n      padding: 30px 24px;\n      gap: 24px;\n    }\n    .cs-oct-flash-media {\n      order: -1;\n      min-height: 240px;\n      border-left: none;\n      border-bottom: 1px solid rgba(255, 255, 255, 0.12);\n    }\n  }\n\n  @media (max-width: 639px) {\n    #cs-october-promos-root {\n      margin: 24px auto 44px;\n      padding: 0 14px;\n    }\n    .cs-oct-title {\n      font-size: 28px;\n    }\n    .cs-oct-flash-content {\n      padding: 0;\n    }\n    .cs-oct-flash-features {\n      grid-template-columns: 1fr;\n      gap: 12px;\n    }\n    .cs-oct-flash-actions-inline {\n      flex-direction: column;\n      align-items: stretch;\n    }\n    .cs-btn-primary-gold {\n      width: 100%;\n    }\n    .cs-modal-title {\n      font-size: 22px;\n    }\n    .cs-card-actions {\n      flex-direction: column;\n      align-items: stretch;\n    }\n    .cs-btn-outline-details {\n      text-align: center;\n    }\n  }\n\n  </style>\n\n  <!-- Шапка секции -->\n  <div class=\"cs-oct-header\">\n    <div class=\"cs-oct-subtitle\">Клиника врачебной и эстетической косметологии «Катрин»</div>\n    <h2 class=\"cs-oct-title\">Специальные предложения ноября</h2>\n    <p class=\"cs-oct-intro\">Индивидуальные медицинские протоколы, глубокое аппаратное обновление кожи и персонализированные программы омоложения. Все процедуры проводятся врачами клиники по показаниям.</p>\n  </div>\n\n  <!-- Главный Hero-баннер -->\n  <div class=\"cs-oct-flash-banner\">\n    <div class=\"cs-oct-flash-content\">\n      <div class=\"cs-oct-flash-tagline\">\n        <span class=\"cs-oct-badge-flash\">Сильная процедура месяца</span>\n        <span class=\"cs-oct-flash-date\">01—30 ноября 2026 года</span>\n      </div>\n      <h3 class=\"cs-oct-flash-title\">Morpheus 8 — глубокое обновление кожи</h3>\n      <div class=\"cs-oct-flash-offer\">Лицо + шея: <mark>55 000 ₽</mark> вместо 68 000 ₽ + <mark>ФДТ в подарок</mark> в тот же день</div>\n      <p class=\"cs-oct-flash-text\">Микроигольчатое радиочастотное ремоделирование тканей лица и шеи для выраженного лифтинга, уплотнения кожи и сглаживания рельефа. После процедуры в тот же день проводится фотодинамическая терапия (ФДТ, 20 мин) стоимостью 3 000 ₽ в подарок.</p>\n      <div class=\"cs-oct-flash-features\">\n        \n          <div class=\"cs-oct-feature-item\">\n            <span class=\"cs-oct-feature-bullet\"></span>\n            <span>Лицо + шея: 55 000 ₽ (вместо 68 000 ₽)</span>\n          </div>\n        \n          <div class=\"cs-oct-feature-item\">\n            <span class=\"cs-oct-feature-bullet\"></span>\n            <span>ФДТ в подарок в тот же день</span>\n          </div>\n        \n          <div class=\"cs-oct-feature-item\">\n            <span class=\"cs-oct-feature-bullet\"></span>\n            <span>Кэшбэк 3–7% на карту лояльности</span>\n          </div>\n        \n          <div class=\"cs-oct-feature-item\">\n            <span class=\"cs-oct-feature-bullet\"></span>\n            <span>Ограниченная запись: 15 мест на ноябрь</span>\n          </div>\n        \n      </div>\n      <div class=\"cs-oct-flash-actions-inline\">\n        <a href=\"#popup:zayavka\" class=\"cs-btn-primary-gold cs-promo-trigger\" data-promo-name=\"Morpheus 8: Лицо + шея (55 000 ₽ + ФДТ в подарок)\">\n          Записаться на Morpheus 8\n        </a>\n        <button type=\"button\" class=\"cs-btn-link-white cs-modal-open-btn\" data-modal-target=\"modal-morpheus\">\n          Правила и регламент процедуры →\n        </button>\n      </div>\n    </div>\n    <div class=\"cs-oct-flash-media\">\n      <img src=\"https://static.tildacdn.com/tila3364-3036-4066-b733-613733333562/promo_morpheus_lift.jpg\" alt=\"Morpheus 8 — глубокое обновление кожи лица и шеи\" class=\"cs-oct-flash-img\" loading=\"lazy\">\n    </div>\n  </div>\n\n  <!-- Сетка из 3 программ -->\n  <div class=\"cs-oct-cards-grid\">\n    \n    <div class=\"cs-oct-card\">\n      <div class=\"cs-card-media\">\n        <img src=\"https://static.tildacdn.com/tila3432-3332-4964-a633-346232316138/promo_pdrn_eyes.jpg\" alt=\"PDRN для зоны век — Свежий взгляд\" class=\"cs-card-img\" loading=\"lazy\">\n        <span class=\"cs-card-badge\">Инъекционный фокус • Зона век</span>\n      </div>\n      <div class=\"cs-card-body\">\n        <div>\n          <h3 class=\"cs-card-title\">PDRN: Программа «Свежий взгляд»</h3>\n          <div class=\"cs-card-aim\">Тонкая кожа век, мелкие морщины, тёмные круги и склонность к отёчности</div>\n          <ul class=\"cs-card-list\">\n            <li>Стимуляция выработки коллагена и укрепление дермы век</li><li>Глубокое клеточное увлажнение и осветление зоны под глазами</li><li>Фиксация цены 4 500 ₽ на весь курс при старте в ноябре</li>\n          </ul>\n        </div>\n        <div>\n          <div class=\"cs-card-value-box\">\n            <div class=\"cs-card-value-main\">4 500 ₽ вместо 6 500 ₽ за процедуру</div>\n            <div class=\"cs-card-value-sub\">Специальная цена ноября на инъекционный сеанс PDRN. При начале медицинского курса в ноябре цена 4 500 ₽ фиксируется на все 3–4 процедуры курса.</div>\n            <div class=\"cs-card-limit-note\">\n              <span class=\"cs-card-limit-dot\"></span>\n              <span>Выгода 2 000 ₽ на каждый визит</span>\n            </div>\n          </div>\n          <div class=\"cs-card-actions\">\n            <a href=\"#popup:zayavka\" class=\"cs-btn-primary-black cs-promo-trigger\" data-promo-name=\"PDRN для зоны век «Свежий взгляд» (4 500 ₽)\">\n              Записаться на PDRN\n            </a>\n            <button type=\"button\" class=\"cs-btn-outline-details cs-modal-open-btn\" data-modal-target=\"modal-pdrn\">\n              Условия\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  \n    <div class=\"cs-oct-card\">\n      <div class=\"cs-card-media\">\n        <img src=\"https://static.tildacdn.com/tild6265-3531-4664-b530-663931333865/promo_intro_consulta.jpg\" alt=\"Первое знакомство с Катрин\" class=\"cs-card-img\" loading=\"lazy\">\n        <span class=\"cs-card-badge\">Для новых пациентов</span>\n      </div>\n      <div class=\"cs-card-body\">\n        <div>\n          <h3 class=\"cs-card-title\">Первое знакомство с «Катрин»</h3>\n          <div class=\"cs-card-aim\">Не уверены, какая процедура вам действительно необходима?</div>\n          <ul class=\"cs-card-list\">\n            <li>Очная медицинская консультация врача-косметолога</li><li>Детальная оценка состояния кожи и эстетической задачи</li><li>Составление персонального плана процедур на 3 месяца</li>\n          </ul>\n        </div>\n        <div>\n          <div class=\"cs-card-value-box\">\n            <div class=\"cs-card-value-main\">1 000 ₽</div>\n            <div class=\"cs-card-value-sub\">Полный зачёт стоимости в счёт любой процедуры в течение 7 дней</div>\n            <div class=\"cs-card-limit-note\">\n              <span class=\"cs-card-limit-dot\"></span>\n              <span>Рабочий лимит: 15 консультаций на ноябрь</span>\n            </div>\n          </div>\n          <div class=\"cs-card-actions\">\n            <a href=\"#popup:zayavka\" class=\"cs-btn-primary-black cs-promo-trigger\" data-promo-name=\"Первое знакомство с Катрин (Консультация с зачетом)\">\n              Записаться к врачу\n            </a>\n            <button type=\"button\" class=\"cs-btn-outline-details cs-modal-open-btn\" data-modal-target=\"modal-intro\">\n              Условия\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  \n    <div class=\"cs-oct-card\">\n      <div class=\"cs-card-media\">\n        <img src=\"https://static.tildacdn.com/tild6638-3666-4136-a337-366633646465/promo_referral_trust.jpg\" alt=\"Программа лояльности Рекомендуй Катрин\" class=\"cs-card-img\" loading=\"lazy\">\n        <span class=\"cs-card-badge\">Программа лояльности • Доверие</span>\n      </div>\n      <div class=\"cs-card-body\">\n        <div>\n          <h3 class=\"cs-card-title\">Привилегия «Рекомендуй Катрин»</h3>\n          <div class=\"cs-card-aim\">Разделите заботу о здоровье и красоте с близкими</div>\n          <ul class=\"cs-card-list\">\n            <li>Новый пациент получает 2 000 бонусов на первый визит</li><li>Вы получаете 2 000 бонусов после оплаченного визита друга</li><li>1 бонус = 1 рубль (списание до 2 000 бонусов за визит)</li>\n          </ul>\n        </div>\n        <div>\n          <div class=\"cs-card-value-box\">\n            <div class=\"cs-card-value-main\">2 000 бонусов другу + 2 000 бонусов вам</div>\n            <div class=\"cs-card-value-sub\">Бонус действует 60 дней при минимальном чеке услуги от 10 000 ₽. Новому пациенту достаточно назвать ваше имя и телефон при записи.</div>\n            <div class=\"cs-card-limit-note\">\n              <span class=\"cs-card-limit-dot\"></span>\n              <span>Для постоянных и новых пациентов</span>\n            </div>\n          </div>\n          <div class=\"cs-card-actions\">\n            <a href=\"#popup:zayavka\" class=\"cs-btn-primary-black cs-promo-trigger\" data-promo-name=\"Программа лояльности: Рекомендуй Катрин\">\n              Рекомендовать клинику\n            </a>\n            <button type=\"button\" class=\"cs-btn-outline-details cs-modal-open-btn\" data-modal-target=\"modal-referral\">\n              Условия\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  \n  </div>\n\n  <!-- Дисклеймер -->\n  <div class=\"cs-oct-disclaimer\">\n    Имеются противопоказания. Необходима предварительная консультация врача-специалиста. Медицинские услуги оказываются ООО «Катрин», лицензия на осуществление медицинской деятельности. Все специальные предложения ноября 2026 года действуют строго по 30.11.2026.\n  </div>\n\n  <!-- Модальные окна -->\n  \n    <div id=\"modal-morpheus\" class=\"cs-modal-backdrop\">\n      <div class=\"cs-modal-dialog\">\n        <button type=\"button\" class=\"cs-modal-close\" aria-label=\"Закрыть\">&times;</button>\n        <div class=\"cs-modal-header\">\n          <div class=\"cs-modal-badge\">Регламент акции • 01.11—30.11.2026</div>\n          <h3 class=\"cs-modal-title\">Morpheus 8 — Глубокое обновление кожи</h3>\n        </div>\n        <div class=\"cs-modal-body\">\n          <h4>1. Суть предложения</h4><p>В ноябре 2026 года процедура микроигольчатого радиочастотного омоложения Morpheus 8 для зоны лица и шеи проводится по специальной цене <strong>55 000 ₽</strong> (обычная стоимость — 68 000 ₽). После процедуры в тот же день пациент получает восстанавливающую фотодинамическую терапию (ФДТ) стоимостью 3 000 ₽ в подарок.</p><h4>2. Протокол фотодинамической терапии (ФДТ)</h4><p>ФДТ проводится на аппарате фотодинамической лампы сразу после сеанса Morpheus 8: 10 минут жёлтого спектра + 10 минут зелёного спектра для ускоренной регенерации, снятия эритемы и выраженного противовоспалительного действия.</p><h4>3. Длительность и планирование</h4><p>Продолжительность комплексного приёма составляет 2,5 часа (анестезия, подготовка, аппаратная процедура Morpheus 8 и сеанс ФДТ). В связи с длительностью протокола количество мест в графике врачей ограничено.</p><h4>4. Лояльность и кэшбэк</h4><p>На процедуру начисляется стандартный кэшбэк клиники (3–7% в зависимости от суммы чека). Дополнительные персональные скидки не суммируются.</p>\n        </div>\n        <div class=\"cs-modal-footer\">\n          <a href=\"#popup:zayavka\" class=\"cs-btn-primary-black cs-promo-trigger\" data-promo-name=\"Morpheus 8: Лицо + шея (55 000 ₽ + ФДТ в подарок)\">\n            Записаться\n          </a>\n        </div>\n      </div>\n    </div>\n  \n    <div id=\"modal-pdrn\" class=\"cs-modal-backdrop\">\n      <div class=\"cs-modal-dialog\">\n        <button type=\"button\" class=\"cs-modal-close\" aria-label=\"Закрыть\">&times;</button>\n        <div class=\"cs-modal-header\">\n          <div class=\"cs-modal-badge\">Регламент акции • 01.11—30.11.2026</div>\n          <h3 class=\"cs-modal-title\">PDRN для зоны век — «Свежий взгляд»</h3>\n        </div>\n        <div class=\"cs-modal-body\">\n          <h4>1. Суть специального предложения</h4><p>В ноябре 2026 года процедура инъекционной полинуклеотидной терапии (PDRN) для периорбитальной зоны проводится по специальной цене <strong>4 500 ₽</strong> вместо 6 500 ₽ за одну процедуру (выгода 2 000 ₽).</p><h4>2. Условия курсового лечения</h4><p>Клинический курс по протоколу составляет 3–4 процедуры с интервалом 2–3 недели. При проведении первой процедуры в период с 01 по 30 ноября 2026 года специальная цена 4 500 ₽ фиксируется за пациентом на все последующие процедуры назначенного курса.</p><h4>3. Показания</h4><p>Снижение тонуса и плотности тонкой кожи век, сеть мелких морщин («гусиные лапки»), потемнение периорбитальной зоны, пастозность и склонность к отёчности. Процедура проводится врачом-косметологом после очной оценки состояния кожи.</p>\n        </div>\n        <div class=\"cs-modal-footer\">\n          <a href=\"#popup:zayavka\" class=\"cs-btn-primary-black cs-promo-trigger\" data-promo-name=\"PDRN для зоны век «Свежий взгляд» (4 500 ₽)\">\n            Записаться\n          </a>\n        </div>\n      </div>\n    </div>\n  \n    <div id=\"modal-intro\" class=\"cs-modal-backdrop\">\n      <div class=\"cs-modal-dialog\">\n        <button type=\"button\" class=\"cs-modal-close\" aria-label=\"Закрыть\">&times;</button>\n        <div class=\"cs-modal-header\">\n          <div class=\"cs-modal-badge\">Регламент программы • Ноябрь 2026</div>\n          <h3 class=\"cs-modal-title\">Первое знакомство с «Катрин»</h3>\n        </div>\n        <div class=\"cs-modal-body\">\n          <h4>1. Для кого разработана программа</h4><p>Для новых пациентов с запросами на омоложение, улучшение качества кожи, удаление пигментации, сосудов, постакне или коррекцию овала лица, которые пока не определились с методом.</p><h4>2. Что включено</h4><ul><li>Очная консультация врача-косметолога клиники.</li><li>Диагностика кожи и анализ противопоказаний.</li><li>Составление персонального плана процедур ориентировочно на 3 месяца.</li></ul><h4>3. Правила зачёта стоимости</h4><p>Стоимость консультации полностью засчитывается в стоимость процедуры, назначенной врачом и проведенной в течение 7 календарных дней с момента консультации. Предложение действует только для пациентов, у которых ранее не было состоявшихся визитов в «Катрин».</p>\n        </div>\n        <div class=\"cs-modal-footer\">\n          <a href=\"#popup:zayavka\" class=\"cs-btn-primary-black cs-promo-trigger\" data-promo-name=\"Первое знакомство с Катрин (Консультация с зачетом)\">\n            Записаться\n          </a>\n        </div>\n      </div>\n    </div>\n  \n    <div id=\"modal-referral\" class=\"cs-modal-backdrop\">\n      <div class=\"cs-modal-dialog\">\n        <button type=\"button\" class=\"cs-modal-close\" aria-label=\"Закрыть\">&times;</button>\n        <div class=\"cs-modal-header\">\n          <div class=\"cs-modal-badge\">Регламент программы • Программа лояльности</div>\n          <h3 class=\"cs-modal-title\">Привилегия «Рекомендуй Катрин»</h3>\n        </div>\n        <div class=\"cs-modal-body\">\n          <h4>1. Для кого действует программа</h4><p>Для постоянных пациентов клиники и их друзей, родственников или коллег, ранее не посещавших «Катрин».</p><h4>2. Привилегия для нового пациента</h4><p>Новый пациент при первом визите получает 2 000 приветственных бонусов (1 бонус = 1 рубль), которыми можно оплатить до 2 000 рублей от стоимости любых медицинских услуг клиники при чеке от 10 000 рублей.</p><h4>3. Вознаграждение постоянного пациента</h4><p>После того как приглашенный друг совершил и оплатил первый визит на сумму от 10 000 рублей, на персональный бонусный счёт постоянного пациента начисляется 2 000 бонусов. Срок действия бонусов — 60 календарных дней.</p><h4>4. Как активировать</h4><p>При записи новому пациенту достаточно назвать ФИО и контактный номер телефона рекомендующего пациента.</p>\n        </div>\n        <div class=\"cs-modal-footer\">\n          <a href=\"#popup:zayavka\" class=\"cs-btn-primary-black cs-promo-trigger\" data-promo-name=\"Программа лояльности: Рекомендуй Катрин\">\n            Записаться\n          </a>\n        </div>\n      </div>\n    </div>\n  \n\n  <!-- Fallback popup -->\n  <div id=\"catherine-promo-fallback-popup\" class=\"cs-modal-backdrop\">\n    <div class=\"cs-modal-dialog\" style=\"max-width: 480px;\">\n      <button type=\"button\" class=\"cs-modal-close\" aria-label=\"Закрыть\">&times;</button>\n      <div class=\"cs-modal-header\">\n        <div class=\"cs-modal-badge\">Онлайн-запись в клинику</div>\n        <h3 class=\"cs-modal-title\" style=\"font-size: 22px;\">Запись по специальному предложению</h3>\n      </div>\n      <form id=\"cs-fallback-record-form\" onsubmit=\"event.preventDefault(); alert('Спасибо! Ваша заявка принята. Администратор клиники «Катрин» свяжется с вами для подтверждения даты и времени визита.'); document.getElementById('catherine-promo-fallback-popup').classList.remove('is-active');\">\n        <div class=\"cs-fallback-form-group\">\n          <label>Выбранная программа</label>\n          <input type=\"text\" id=\"cs-fallback-promo-input\" readonly value=\"\">\n        </div>\n        <div class=\"cs-fallback-form-group\">\n          <label>Ваше имя</label>\n          <input type=\"text\" required placeholder=\"Как к вам обращаться?\">\n        </div>\n        <div class=\"cs-fallback-form-group\">\n          <label>Номер телефона</label>\n          <input type=\"tel\" required placeholder=\"+7 (___) ___-__-__\">\n        </div>\n        <button type=\"submit\" class=\"cs-btn-primary-black\" style=\"width: 100%; padding: 15px;\">\n          Отправить заявку\n        </button>\n      </form>\n    </div>\n  </div>\n</div>\n";

  function initCatherinePromos() {
    var target = document.getElementById('catherine-promos-container') ||
                 document.getElementById('cs-october-promos-root');

    if (!target) {
      var t123 = document.querySelector('.r[data-record-type="131"] .t123') ||
                 document.querySelector('.t-records');
      target = document.createElement('div');
      target.id = 'catherine-promos-container';
      if (t123 && t123.parentNode) {
        t123.parentNode.insertBefore(target, t123);
      } else {
        document.body.prepend(target);
      }
    }

    target.innerHTML = htmlContent;

    // Инициализация модалок
    var openButtons = target.querySelectorAll('.cs-modal-open-btn');
    var closeButtons = target.querySelectorAll('.cs-modal-close');
    var backdrops = target.querySelectorAll('.cs-modal-backdrop');

    function closeModal(modal) {
      if (modal) {
        modal.classList.remove('is-active');
        document.body.style.overflow = '';
      }
    }

    openButtons.forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        var targetId = this.getAttribute('data-modal-target');
        var targetModal = target.querySelector('#' + targetId) || document.getElementById(targetId);
        if (targetModal) {
          targetModal.classList.add('is-active');
          document.body.style.overflow = 'hidden';
        }
      });
    });

    closeButtons.forEach(function(btn) {
      btn.addEventListener('click', function() {
        var modal = this.closest('.cs-modal-backdrop');
        closeModal(modal);
      });
    });

    backdrops.forEach(function(backdrop) {
      backdrop.addEventListener('click', function(e) {
        if (e.target === this) {
          closeModal(this);
        }
      });
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        backdrops.forEach(function(modal) {
          if (modal.classList.contains('is-active')) {
            closeModal(modal);
          }
        });
      }
    });

    // Интеграция с официальной формой записи Тильды (#popup:zayavka / rec608825704)
    var promoButtons = target.querySelectorAll('.cs-promo-trigger');

    promoButtons.forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        var promoName = this.getAttribute('data-promo-name') || 'Специальное предложение месяца';

        var parentModal = this.closest('.cs-modal-backdrop');
        if (parentModal) {
          closeModal(parentModal);
        }

        var tildaPopup = document.querySelector('[data-tooltip-hook="#popup:zayavka"]') ||
                         document.getElementById('rec608825704') ||
                         document.querySelector('.t-popup');

        if (tildaPopup) {
          var descr = tildaPopup.querySelector('.t-popup__descr, .t-form__text, .t-descr');
          if (descr) {
            if (!descr.getAttribute('data-original-text')) {
              descr.setAttribute('data-original-text', descr.innerHTML);
            }
            descr.innerHTML = descr.getAttribute('data-original-text') +
              '<br><strong style="color: #c5a265; display: inline-block; margin-top: 6px;">Запись по акции: ' + promoName + '</strong>';
          }

          var form = tildaPopup.querySelector('form');
          if (form) {
            var hiddenInput = form.querySelector('input[name="promo_name"]');
            if (!hiddenInput) {
              hiddenInput = document.createElement('input');
              hiddenInput.type = 'hidden';
              hiddenInput.name = 'promo_name';
              form.appendChild(hiddenInput);
            }
            hiddenInput.value = promoName;
          }

          var popupId = tildaPopup.getAttribute('data-record-id') || '608825704';
          if (typeof window.t702_showPopup === 'function') {
            window.t702_showPopup(popupId);
          } else if (typeof window.t_popup__showPopup === 'function') {
            window.t_popup__showPopup(popupId);
          }
        } else {
          e.preventDefault();
          var fallbackPopup = document.getElementById('catherine-promo-fallback-popup');
          var fallbackInput = document.getElementById('cs-fallback-promo-input');
          if (fallbackPopup && fallbackInput) {
            fallbackInput.value = promoName;
            fallbackPopup.classList.add('is-active');
            document.body.style.overflow = 'hidden';
          }
        }
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initCatherinePromos);
  } else {
    initCatherinePromos();
  }
})();
